#include "RecoveryManager.h"
#include "BootManager.h"
#include "../infrastructure/TransactionJournal.h"
#include "../infrastructure/AssetManager.h"
#include "../services/StorageService.h"
#include "../services/UpdateService.h"
#include <esp_ota_ops.h>
namespace hp { RecoveryManager& RecoveryManager::instance(){static RecoveryManager r;return r;} bool RecoveryManager::required()const{return BootManager::instance().state().safeMode||TransactionJournal::instance().state()==UpdateState::RecoveryRequired||ConfigService::instance().newerSchema();} String RecoveryManager::reason()const{if(ConfigService::instance().newerSchema())return "Konfiguration stammt aus neuerer Firmware";if(BootManager::instance().state().safeMode)return "Bootloop-Schutz aktiv";if(TransactionJournal::instance().state()==UpdateState::RecoveryRequired)return "Update-Recovery erforderlich";return "";} bool RecoveryManager::execute(RecoveryAction a,bool confirmed){auto&c=ConfigService::instance();switch(a){case RecoveryAction::Restart:ESP.restart();return true;case RecoveryAction::PreviousFirmware:return esp_ota_mark_app_invalid_rollback_and_reboot()==ESP_OK;case RecoveryAction::RepairAssets:{String e;if(TransactionJournal::instance().state()==UpdateState::RecoveryRequired&&UpdateService::instance().recoverAssetsFromBackup(e))return true;return AssetManager::instance().verifyAll();}case RecoveryAction::ResetNetwork:return c.reset(ConfigScope::Network);case RecoveryAction::ResetUi:return c.reset(ConfigScope::Ui);case RecoveryAction::ResetWebApps:return StorageService::instance().remove(StorageArea::UserData,"/webapps/apps.bin");case RecoveryAction::ResetCalendarAccounts:return c.reset(ConfigScope::CalendarAccounts);case RecoveryAction::ResetMedia:return c.reset(ConfigScope::Media);case RecoveryAction::ResetUserSettings:return c.reset(ConfigScope::UserSettings);case RecoveryAction::FullFactoryReset:if(!confirmed)return false;{bool ok=c.reset(ConfigScope::AllUser);ok&=StorageService::instance().removeTree(StorageArea::UserData,"/webapps");ok&=StorageService::instance().removeTree(StorageArea::UserData,"/calendar");return ok;}}return false;} }
